const allProductsToSeed = [...existingVpnProducts, ...additionalVpnProducts, ...simOfferProducts];

async function seedProducts() {
  try {
    await connectDB();
    console.log(`🌱 Starting MongoDB Atlas Seed for ${allProductsToSeed.length} Products (38 VPN + 98 SIM)...`);

    for (const item of allProductsToSeed) {
      const isAvailable = item.inStock !== false;
      const productPayload = {
        productId: item.id,
        title: item.title,
        category: item.category || 'VPN',
        subtitle: item.subtitle || '100% Full Fresh VPN ✅',
        operator: item.operator,
        price: item.price,
        originalPrice: item.originalPrice || (item.price + 20),
        duration: item.duration || '30 Days',
        rating: item.rating || 4.8,
        reviews: item.reviews || 120,
        tag: item.badge || item.tag,
        badgeColor: item.badgeColor,
        logo: item.logo || item.image,
        image: item.image || item.logo,
        inStock: isAvailable,
        stock: item.stock || (isAvailable ? 'In Stock' : 'Stock Out'),
        features: item.features || ['Direct Recharge / Drive Pack', '100% Activation Guarantee', 'Full Support']
      };

      const updated = await Product.findOneAndUpdate(
        { productId: item.id },
        { $set: productPayload },
        { upsert: true, returnDocument: 'after' }
      );
      console.log(` ✅ Seeded [${updated.category.toUpperCase()}] ${updated.title} -> ৳${updated.price}`);
    }

    console.log(`🎉 Successfully seeded ${allProductsToSeed.length} Products in MongoDB Atlas!`);
    process.exit(0);
  } catch (err) {
    console.error('❌ Seed error:', err);
    process.exit(1);
  }
}

seedProducts();
